    -- 7. TỒN KHO
    SELECT sp.id,k.id,
           COALESCE(SUM(CASE WHEN gdk.loai_giao_dich IN ('NHAP_KHO','NHAP_DAU_KY','DIEU_CHINH_TANG') THEN gdk.so_luong
                            WHEN gdk.loai_giao_dich IN ('XUAT_KHO','DIEU_CHINH_GIAM') THEN -gdk.so_luong ELSE 0 END),0),now()
    FROM san_pham sp CROSS JOIN kho k
    LEFT JOIN giao_dich_kho gdk ON gdk.san_pham_id=sp.id AND gdk.kho_id=k.id
    GROUP BY sp.id,k.id;

